<?php
declare(strict_types=1);
use Vendi\Database\Connection;use Vendi\Branches\BranchContextService;use Vendi\Http\ApiGuard;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=$_SESSION['user']??null;if(!$u)throw new RuntimeException('Sesión requerida');$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);$branch=(new BranchContextService($db))->active($u);ApiGuard::branch($db,$u,$branch);$q=$db->prepare("SELECT * FROM cash_sessions WHERE business_id=? AND branch_id=? AND user_id=? AND status='open' ORDER BY id DESC LIMIT 1");$q->execute([(int)$u['business_id'],$branch,(int)$u['id']]);$s=$q->fetch();if(!$s)throw new RuntimeException('No hay caja abierta.');$m=$db->prepare("SELECT type,COALESCE(SUM(amount),0) total FROM cash_movements WHERE cash_session_id=? GROUP BY type");$m->execute([$s['id']]);$x=['sale'=>0,'deposit'=>0,'refund'=>0,'withdrawal'=>0];foreach($m->fetchAll() as $r)$x[$r['type']]=(float)$r['total'];$expected=(float)$s['opening_amount']+$x['sale']+$x['deposit']-$x['refund']-$x['withdrawal'];echo json_encode(['ok'=>true,'session_id'=>(int)$s['id'],'opening'=>(float)$s['opening_amount'],'sales'=>$x['sale'],'deposits'=>$x['deposit'],'refunds'=>$x['refund'],'withdrawals'=>$x['withdrawal'],'expected'=>$expected]);}catch(Throwable $e){http_response_code(422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}